package main

import (
	"encoding/binary"
	"fmt"
	"net"
	"os"
	"time"
)

// icmpHeader represents an ICMP header: Type(1) Code(1) Checksum(2) ID(2) Seq(2)
type icmpHeader struct {
	Type     uint8
	Code     uint8
	Checksum uint16
	ID       uint16
	Seq      uint16
}

// checksum computes the 16-bit one's complement sum over a byte slice
func checksum(data []byte) uint16 {
	var sum uint32
	for i := 0; i+1 < len(data); i += 2 {
		sum += uint32(binary.BigEndian.Uint16(data[i : i+2]))
	}
	if len(data)%2 != 0 {               // Odd byte: pad with zero
		sum += uint32(data[len(data)-1]) << 8
	}
	for sum>>16 != 0 {                  // Fold 32-bit sum to 16 bits
		sum = (sum & 0xFFFF) + (sum >> 16)
	}
	return ^uint16(sum)                 // One's complement
}

func buildICMPEcho(id, seq uint16) []byte {
	pkt := make([]byte, 8)              // ICMP header is 8 bytes
	pkt[0] = 8                         // Type 8 = Echo Request
	pkt[1] = 0                         // Code 0
	binary.BigEndian.PutUint16(pkt[4:], id)
	binary.BigEndian.PutUint16(pkt[6:], seq)
	// Checksum field starts at zero — compute over the full header
	csum := checksum(pkt)
	binary.BigEndian.PutUint16(pkt[2:], csum) // Write computed checksum at offset 2
	return pkt
}

func main() {
	conn, err := net.Dial("ip4:icmp", "8.8.8.8") // Raw ICMP socket — needs CAP_NET_RAW
	if err != nil {
		fmt.Fprintf(os.Stderr, "[-] %v (run as root or with CAP_NET_RAW)\n", err)
		os.Exit(1)
	}
	defer conn.Close()
	conn.SetDeadline(time.Now().Add(3 * time.Second))
	pkt := buildICMPEcho(0x1337, 1)     // ID=0x1337, Sequence=1
	conn.Write(pkt)
	rbuf := make([]byte, 64)
	n, _ := conn.Read(rbuf)
	fmt.Printf("[+] Reply: %d bytes — type=%d\n", n, rbuf[0])
}

package main

import (
	"fmt"
	"io/fs"
	"os"
	"path/filepath"
	"sync"
	"time"
)

// FileJob represents one file to process
type FileJob struct {
	Path string
	Size int64
}

// AuditEntry records what the simulator did to one file
type AuditEntry struct {
	Path      string
	Action    string    // "read", "staged", "skipped"
	Duration  time.Duration
	Timestamp time.Time
}

// walkFiles sends all regular files under root to the jobs channel
func walkFiles(root string, jobs chan<- FileJob) {
	defer close(jobs)                          // Signal workers that enumeration is done
	filepath.WalkDir(root, func(path string, d fs.DirEntry, err error) error {
		if err != nil || d.IsDir() {
			return nil                         // Skip errors and directories silently
		}
		info, err := d.Info()
		if err != nil {
			return nil
		}
		jobs <- FileJob{Path: path, Size: info.Size()} // Send job to worker pool
		return nil
	})
}

// worker processes FileJobs from the jobs channel and sends AuditEntrys to results
func worker(id int, jobs <-chan FileJob, results chan<- AuditEntry, wg *sync.WaitGroup) {
	defer wg.Done()                            // Always signal completion
	for job := range jobs {                    // Range over channel — exits when channel closes
		start := time.Now()
		_, err := os.ReadFile(job.Path)        // Read file — generate file-access telemetry
		action := "read"
		if err != nil {
			action = "skipped"
		}
		results <- AuditEntry{
			Path:      job.Path,
			Action:    action,
			Duration:  time.Since(start),
			Timestamp: time.Now(),
		}
	}
}

func runPool(root string, workerCount int) []AuditEntry {
	jobs    := make(chan FileJob, 100)          // Buffered: walker can run ahead of workers
	results := make(chan AuditEntry, 100)
	var wg sync.WaitGroup
	for i := 0; i < workerCount; i++ {         // Launch fixed pool of workers
		wg.Add(1)
		go worker(i, jobs, results, &wg)
	}
	go walkFiles(root, jobs)                   // Walker in its own goroutine
	go func() { wg.Wait(); close(results) }()  // Close results when all workers done
	var audit []AuditEntry
	for entry := range results {
		audit = append(audit, entry)
	}
	return audit
}

